}

impl SnapshotStore {
    pub fn new(initial: Arc<Snapshot>) -> Self {
        Self { current: std::sync::RwLock::new(initial) }
    }

    /// Conditionally swap to new_snap if its version is newer.
    /// Returns true if the swap was actually applied.
    ///
    /// BUGGY IMPLEMENTATION: mutates `applied` inside the rcu closure.
    /// The rcu closure may run multiple times under CAS contention,
    /// making external mutation of `applied` unreliable.
    pub fn try_update(&self, new_snap: Arc<Snapshot>) -> bool {
        let mut applied = false;
        // Simulating rcu: in real arc-swap this closure is a CAS retry loop
        let mut guard = self.current.write().unwrap();
        let current = Arc::clone(&*guard);
        // closure body (runs once here but multiple times in real rcu under contention)
        let next = if new_snap.version > current.version {
            applied = true;  // BUG: unreliable if closure runs multiple times
            Arc::clone(&new_snap)
        } else {
            Arc::clone(&current)
        };
        *guard = next;
        applied
    }
}
